      SUBROUTINE RDDATAC---- READ THE DATA UP TO THE NEXT SENTINELC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'NFLAGS.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'NHORN.CIN'      INCLUDE 'RDHIST.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'SVALUE.CIN'      INCLUDE 'UROT.CIN'C-----------------------------------------------------------------------C      NEL = 0      I = 1      ISTOR(1) = 1      FLUSHL = .FALSE.      NMARKS = 0      UROT = 1.0/RADIAN      SVALUE(1) = PI      SVALUE(2) = 2.0*PI      SVALUE(3) = RADIAN      SVALUE(4) = 1.0/RADIAN      SVALUE(5) = EXP(1.0)      SVALUE(6) = EMASS      SVALUE(8) = CLIGHT      SVALUE(10) = 1.0/SVALUE(9)      REMOVE = .FALSE.      INSERT = .FALSE.      NFLAGS = 0      NHSTS = 0      NHORN = 0C      IF (BRD) GO TO 200C  110 CALL RDELMT      IF (ENDFIL) GO TO 400      IF (NTYPE .EQ. 73) GO TO 400      GO TO 110C  200 READ (NDATA) NEL, IEL      NELP1 = NEL + 1      READ (NDATA) (DATA(I), I = 1, IEL)      READ (NDATA) (TIE(I), I = 1, IEL)      READ (NDATA) (ISTOR(N), N = 1, NELP1)      READ (NDATA) (NDESCR(N), N = 1, NEL)      READ (NDATA) (LABEL(N), N = 1, NEL)C  400 FLUSHL = FLUSHL .OR. NFAIL .GE. 1      CALL RDEND      RETURN      END